/**
 * ai-product-knowledge/index.ts — AI 产品知识库
 *
 * 为诊断 Phase 1 提供 AI 产品生态知识：
 *   - SKU 查询（模型/产品/API 服务）
 *   - 版本兼容性检查
 *   - 模糊搜索
 *   - 团队使用的 AI 工具清单分析
 *
 * 用途：诊断时识别团队是否使用了过时的 AI 工具、是否存在
 * 关键工具的版本兼容风险、或是否遗漏了能显著提升效率的 AI 产品。
 */
export interface AIProduct {
    /** 产品标识 */
    id: string;
    /** 产品名称 */
    name: string;
    /** 厂商 */
    vendor: string;
    /** 类别 */
    category: AIProductCategory;
    /** 当前最新版本 */
    latestVersion: string;
    /** 最低稳定版本 */
    minStableVersion: string;
    /** 已弃用版本列表 */
    deprecatedVersions: string[];
    /** 发布日期 */
    releaseDate: string;
    /** 产品描述 */
    description: string;
    /** 适用团队规模 */
    suitableFor: ('startup' | 'sme' | 'enterprise')[];
    /** 关键词（用于搜索） */
    keywords: string[];
    /** 替代产品 ID 列表 */
    alternatives: string[];
    /** 价格区间（月/用户） */
    pricingTier: 'free' | 'low' | 'medium' | 'high' | 'enterprise';
}
export type AIProductCategory = 'llm-platform' | 'agent-framework' | 'vector-database' | 'monitoring' | 'prompt-engineering' | 'fine-tuning' | 'code-assistant' | 'design-ai' | 'data-ai' | 'automation';
export interface ProductQuery {
    category?: AIProductCategory;
    vendor?: string;
    keyword?: string;
    pricingTier?: AIProduct['pricingTier'];
    suitableFor?: AIProduct['suitableFor'][number];
}
/** 团队使用的 AI 工具清单条目 */
export interface TeamAIToolEntry {
    productId: string;
    /** 当前使用的版本 */
    version: string;
    /** 使用范围 */
    usageScope: 'team-wide' | 'department' | 'individual';
    /** 满意度 1-10 */
    satisfaction: number;
    /** 月度成本（元） */
    monthlyCost: number;
}
/** 工具清单分析结果 */
export interface AIInventoryAnalysis {
    /** 已弃用/过时的工具 */
    outdatedTools: {
        product: AIProduct;
        currentVersion: string;
        recommendedVersion: string;
    }[];
    /** 存在版本兼容风险的工具 */
    versionRisks: {
        product: AIProduct;
        currentVersion: string;
        risk: string;
    }[];
    /** 推荐的替代品 */
    recommendedAlternatives: {
        current: AIProduct;
        alternatives: AIProduct[];
    }[];
    /** 遗漏的关键品类 */
    missingCategories: AIProductCategory[];
    /** 工具重叠（同一品类多个产品） */
    overlaps: {
        category: AIProductCategory;
        products: AIProduct[];
    }[];
    /** 综合评分 0-100 */
    overallScore: number;
}
/** 查询产品 */
export declare function queryProducts(query?: ProductQuery): AIProduct[];
/** 按 ID 获取产品 */
export declare function getProduct(id: string): AIProduct | null;
/** 检查版本是否为已弃用版本 */
export declare function isVersionDeprecated(productId: string, version: string): boolean;
/** 检查版本是否低于最低稳定版本 */
export declare function isVersionOutdated(productId: string, version: string): boolean;
/** 获取所有产品类别 */
export declare function getCategories(): AIProductCategory[];
/** 模糊搜索（基于产品名+关键词得分） */
export declare function fuzzySearch(term: string, maxResults?: number): AIProduct[];
/** 分析团队 AI 工具清单 */
export declare function analyzeAIInventory(tools: TeamAIToolEntry[]): AIInventoryAnalysis;
